-- Pokelizer Stage 1 physical model. SQLite >= 3.37 (STRICT).
-- Generated by backend/tools/build_schema.py; edit source + regenerate.
-- Empty database only. Existing databases use explicit migrations via Python CLI.
PRAGMA foreign_keys = ON;
PRAGMA recursive_triggers = ON;

CREATE TABLE USUARIO (
    id_usuario INTEGER PRIMARY KEY,
    nome_usuario TEXT NOT NULL COLLATE NOCASE UNIQUE CHECK(length(trim(nome_usuario))>=3),
    email TEXT NOT NULL COLLATE NOCASE UNIQUE CHECK(length(trim(email))>3 AND instr(email,'@')>1),
    senha_hash TEXT NOT NULL CHECK(length(senha_hash)>=40),
    data_cadastro TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
) STRICT;

CREATE TABLE ESPECIE (
    id_especie INTEGER PRIMARY KEY,
    numero_nacional INTEGER NOT NULL UNIQUE CHECK(numero_nacional>0),
    nome_pt TEXT NOT NULL CHECK(length(trim(nome_pt))>0),
    nome_en TEXT,
    geracao_origem INTEGER CHECK(geracao_origem>0),
    status_catalogo TEXT NOT NULL DEFAULT 'rascunho' CHECK(status_catalogo IN ('rascunho','completo')),
    fonte_url TEXT,
    data_verificacao TEXT,
    CHECK((fonte_url IS NULL)=(data_verificacao IS NULL)),
    CHECK(data_verificacao IS NULL OR (date(data_verificacao,'+0 days') IS NOT NULL AND date(data_verificacao,'+0 days')=data_verificacao)),
    CHECK(status_catalogo!='completo' OR (fonte_url IS NOT NULL AND length(trim(fonte_url))>0))
) STRICT;

CREATE TABLE FORMA (
    id_forma INTEGER PRIMARY KEY,
    id_especie INTEGER NOT NULL REFERENCES ESPECIE(id_especie) ON UPDATE RESTRICT ON DELETE RESTRICT,
    codigo_forma TEXT NOT NULL CHECK(length(trim(codigo_forma))>0),
    nome_forma TEXT NOT NULL CHECK(length(trim(nome_forma))>0),
    categoria TEXT NOT NULL DEFAULT 'padrao' CHECK(length(trim(categoria))>0),
    estado_forma TEXT CHECK(estado_forma IN ('permanente','condicional','temporario','nao_verificado')),
    descricao TEXT,
    forma_padrao INTEGER NOT NULL DEFAULT 0 CHECK(forma_padrao IN (0,1)),
    fonte_url TEXT,
    data_verificacao TEXT,
    UNIQUE(id_especie,codigo_forma),
    CHECK((fonte_url IS NULL)=(data_verificacao IS NULL)),
    CHECK(data_verificacao IS NULL OR (date(data_verificacao,'+0 days') IS NOT NULL AND date(data_verificacao,'+0 days')=data_verificacao))
) STRICT;
CREATE UNIQUE INDEX ux_forma_padrao_por_especie ON FORMA(id_especie) WHERE forma_padrao=1;

CREATE TABLE JOGO (
    id_jogo INTEGER PRIMARY KEY,
    nome TEXT NOT NULL COLLATE NOCASE UNIQUE CHECK(length(trim(nome))>0),
    categoria TEXT,
    geracao INTEGER CHECK(geracao>0),
    plataforma TEXT,
    data_lancamento TEXT CHECK(data_lancamento IS NULL OR (date(data_lancamento,'+0 days') IS NOT NULL AND date(data_lancamento,'+0 days')=data_lancamento)),
    fonte_url TEXT,
    data_verificacao TEXT,
    CHECK((fonte_url IS NULL)=(data_verificacao IS NULL)),
    CHECK(data_verificacao IS NULL OR (date(data_verificacao,'+0 days') IS NOT NULL AND date(data_verificacao,'+0 days')=data_verificacao))
) STRICT;

CREATE TABLE DADOS_FORMA_JOGO (
    id_dados_forma INTEGER PRIMARY KEY,
    id_forma INTEGER NOT NULL REFERENCES FORMA(id_forma) ON UPDATE RESTRICT ON DELETE RESTRICT,
    id_jogo INTEGER NOT NULL REFERENCES JOGO(id_jogo) ON UPDATE RESTRICT ON DELETE RESTRICT,
    status_presenca TEXT NOT NULL DEFAULT 'nao_verificada' CHECK(status_presenca IN ('nativa','transferivel','ausente','nao_verificada')),
    pode_ser_registrada TEXT CHECK(pode_ser_registrada IN ('sim','nao')),
    motivo_registro TEXT,
    status_tipos TEXT NOT NULL DEFAULT 'nao_verificado' CHECK(status_tipos IN ('aplicavel','nao_aplicavel','nao_verificado')),
    altura_m REAL CHECK(altura_m>=0),
    peso_kg REAL CHECK(peso_kg>=0),
    hp_base INTEGER CHECK(hp_base>=0),
    ataque_base INTEGER CHECK(ataque_base>=0),
    defesa_base INTEGER CHECK(defesa_base>=0),
    ataque_especial_base INTEGER CHECK(ataque_especial_base>=0),
    defesa_especial_base INTEGER CHECK(defesa_especial_base>=0),
    velocidade_base INTEGER CHECK(velocidade_base>=0),
    fonte_url TEXT,
    data_verificacao TEXT,
    UNIQUE(id_forma,id_jogo),
    CHECK((fonte_url IS NULL)=(data_verificacao IS NULL)),
    CHECK(data_verificacao IS NULL OR (date(data_verificacao,'+0 days') IS NOT NULL AND date(data_verificacao,'+0 days')=data_verificacao)),
    CHECK((status_presenca='nao_verificada' AND pode_ser_registrada IS NULL AND status_tipos='nao_verificado') OR (fonte_url IS NOT NULL AND length(trim(fonte_url))>0)),
    CHECK(status_presenca!='ausente' OR pode_ser_registrada IS NULL OR pode_ser_registrada='nao')
) STRICT;

CREATE TABLE TIPO (
    id_tipo INTEGER PRIMARY KEY,
    nome_tipo TEXT NOT NULL COLLATE NOCASE UNIQUE CHECK(length(trim(nome_tipo))>0)
) STRICT;
CREATE TABLE TIPO_FORMA_JOGO (
    id_dados_forma INTEGER NOT NULL REFERENCES DADOS_FORMA_JOGO(id_dados_forma) ON UPDATE RESTRICT ON DELETE CASCADE,
    id_tipo INTEGER NOT NULL REFERENCES TIPO(id_tipo) ON UPDATE RESTRICT ON DELETE RESTRICT,
    posicao INTEGER NOT NULL CHECK(posicao IN (1,2)),
    PRIMARY KEY(id_dados_forma,id_tipo),
    UNIQUE(id_dados_forma,posicao)
) STRICT;

CREATE TABLE HABILIDADE (
    id_habilidade INTEGER PRIMARY KEY,
    nome TEXT NOT NULL COLLATE NOCASE UNIQUE CHECK(length(trim(nome))>0),
    descricao TEXT
) STRICT;
CREATE TABLE HABILIDADE_FORMA_JOGO (
    id_habilidade_forma INTEGER PRIMARY KEY,
    id_dados_forma INTEGER NOT NULL REFERENCES DADOS_FORMA_JOGO(id_dados_forma) ON UPDATE RESTRICT ON DELETE CASCADE,
    id_habilidade INTEGER NOT NULL REFERENCES HABILIDADE(id_habilidade) ON UPDATE RESTRICT ON DELETE RESTRICT,
    slot TEXT NOT NULL CHECK(length(trim(slot))>0),
    condicao TEXT,
    fonte_url TEXT NOT NULL CHECK(length(trim(fonte_url))>0),
    data_verificacao TEXT NOT NULL CHECK(date(data_verificacao,'+0 days') IS NOT NULL AND date(data_verificacao,'+0 days')=data_verificacao),
    UNIQUE(id_dados_forma,id_habilidade,slot),
    UNIQUE(id_dados_forma,slot),
    UNIQUE(id_habilidade_forma,id_dados_forma)
) STRICT;

CREATE TABLE METODO_OBTENCAO (
    id_metodo INTEGER PRIMARY KEY,
    nome TEXT NOT NULL COLLATE NOCASE UNIQUE CHECK(length(trim(nome))>0),
    descricao TEXT
) STRICT;
CREATE TABLE METODO_FORMA_JOGO (
    id_dados_forma INTEGER NOT NULL REFERENCES DADOS_FORMA_JOGO(id_dados_forma) ON UPDATE RESTRICT ON DELETE CASCADE,
    id_metodo INTEGER NOT NULL REFERENCES METODO_OBTENCAO(id_metodo) ON UPDATE RESTRICT ON DELETE RESTRICT,
    condicao TEXT,
    fonte_url TEXT NOT NULL CHECK(length(trim(fonte_url))>0),
    data_verificacao TEXT NOT NULL CHECK(date(data_verificacao,'+0 days') IS NOT NULL AND date(data_verificacao,'+0 days')=data_verificacao),
    PRIMARY KEY(id_dados_forma,id_metodo)
) STRICT;

CREATE TABLE ATRIBUTO_BATALHA (
    id_atributo INTEGER PRIMARY KEY,
    codigo TEXT NOT NULL UNIQUE CHECK(length(trim(codigo))>0),
    nome TEXT NOT NULL CHECK(length(trim(nome))>0)
) STRICT;
CREATE TABLE NATUREZA (
    id_natureza INTEGER PRIMARY KEY,
    nome TEXT NOT NULL COLLATE NOCASE UNIQUE CHECK(length(trim(nome))>0),
    atributo_aumentado TEXT REFERENCES ATRIBUTO_BATALHA(codigo) ON UPDATE RESTRICT ON DELETE RESTRICT,
    atributo_reduzido TEXT REFERENCES ATRIBUTO_BATALHA(codigo) ON UPDATE RESTRICT ON DELETE RESTRICT,
    estado_efeito TEXT NOT NULL DEFAULT 'nao_verificado' CHECK(estado_efeito IN ('neutro','modificador','nao_verificado')),
    fonte_url TEXT,
    data_verificacao TEXT,
    CHECK((fonte_url IS NULL)=(data_verificacao IS NULL)),
    CHECK(data_verificacao IS NULL OR (date(data_verificacao,'+0 days') IS NOT NULL AND date(data_verificacao,'+0 days')=data_verificacao)),
    CHECK((estado_efeito IN ('neutro','nao_verificado') AND atributo_aumentado IS NULL AND atributo_reduzido IS NULL) OR (estado_efeito='modificador' AND atributo_aumentado IS NOT NULL AND atributo_reduzido IS NOT NULL AND atributo_aumentado!=atributo_reduzido)),
    CHECK(estado_efeito='nao_verificado' OR (fonte_url IS NOT NULL AND length(trim(fonte_url))>0))
) STRICT;

CREATE TABLE MECANICA_JOGO (
    id_mecanica INTEGER PRIMARY KEY,
    id_jogo INTEGER NOT NULL REFERENCES JOGO(id_jogo) ON UPDATE RESTRICT ON DELETE RESTRICT,
    versao TEXT NOT NULL CHECK(length(trim(versao))>0),
    usa_natureza TEXT NOT NULL DEFAULT 'nao_verificado' CHECK(usa_natureza IN ('sim','nao','nao_verificado')),
    usa_habilidade TEXT NOT NULL DEFAULT 'nao_verificado' CHECK(usa_habilidade IN ('sim','nao','nao_verificado')),
    usa_nivel TEXT NOT NULL DEFAULT 'nao_verificado' CHECK(usa_nivel IN ('sim','nao','nao_verificado')),
    nivel_minimo INTEGER CHECK(nivel_minimo>=0),
    nivel_maximo INTEGER CHECK(nivel_maximo>=nivel_minimo),
    data_inicio TEXT,
    data_fim TEXT,
    fonte_url TEXT,
    data_verificacao TEXT,
    UNIQUE(id_jogo,versao),
    CHECK((fonte_url IS NULL)=(data_verificacao IS NULL)),
    CHECK(data_verificacao IS NULL OR (date(data_verificacao,'+0 days') IS NOT NULL AND date(data_verificacao,'+0 days')=data_verificacao)),
    CHECK(data_inicio IS NULL OR (date(data_inicio,'+0 days') IS NOT NULL AND date(data_inicio,'+0 days')=data_inicio)),
    CHECK(data_fim IS NULL OR (date(data_fim,'+0 days') IS NOT NULL AND date(data_fim,'+0 days')=data_fim)),
    CHECK(data_fim IS NULL OR data_inicio IS NULL OR data_fim>=data_inicio),
    CHECK(usa_nivel='sim' OR (nivel_minimo IS NULL AND nivel_maximo IS NULL)),
    CHECK((usa_natureza='nao_verificado' AND usa_habilidade='nao_verificado' AND usa_nivel='nao_verificado') OR (fonte_url IS NOT NULL AND length(trim(fonte_url))>0))
) STRICT;

CREATE TABLE SISTEMA_ATRIBUTO (
    id_sistema_atributo INTEGER PRIMARY KEY,
    codigo TEXT NOT NULL UNIQUE CHECK(length(trim(codigo))>0),
    nome TEXT NOT NULL CHECK(length(trim(nome))>0),
    descricao TEXT
) STRICT;
CREATE TABLE MECANICA_SISTEMA_ATRIBUTO (
    id_mecanica_sistema_atributo INTEGER PRIMARY KEY,
    id_mecanica INTEGER NOT NULL REFERENCES MECANICA_JOGO(id_mecanica) ON UPDATE RESTRICT ON DELETE RESTRICT,
    id_sistema_atributo INTEGER NOT NULL REFERENCES SISTEMA_ATRIBUTO(id_sistema_atributo) ON UPDATE RESTRICT ON DELETE RESTRICT,
    aplicabilidade TEXT NOT NULL DEFAULT 'nao_verificado' CHECK(aplicabilidade IN ('aplicavel','nao_aplicavel','nao_verificado')),
    unidade TEXT,
    valor_minimo INTEGER CHECK(valor_minimo>=0),
    valor_maximo_atributo INTEGER CHECK(valor_maximo_atributo>=valor_minimo),
    valor_maximo_total INTEGER CHECK(valor_maximo_total>=0),
    limite_total_status TEXT NOT NULL DEFAULT 'nao_verificado' CHECK(limite_total_status IN ('confirmado','nao_aplicavel','nao_verificado')),
    fonte_url TEXT,
    data_verificacao TEXT,
    UNIQUE(id_mecanica,id_sistema_atributo),
    CHECK((fonte_url IS NULL)=(data_verificacao IS NULL)),
    CHECK(data_verificacao IS NULL OR (date(data_verificacao,'+0 days') IS NOT NULL AND date(data_verificacao,'+0 days')=data_verificacao)),
    CHECK(aplicabilidade='aplicavel' OR (valor_minimo IS NULL AND valor_maximo_atributo IS NULL AND valor_maximo_total IS NULL AND limite_total_status='nao_verificado')),
    CHECK((limite_total_status='confirmado' AND valor_maximo_total IS NOT NULL) OR (limite_total_status!='confirmado' AND valor_maximo_total IS NULL)),
    CHECK(aplicabilidade='nao_verificado' OR (fonte_url IS NOT NULL AND length(trim(fonte_url))>0))
) STRICT;
-- Some mechanics do not have all globally named attributes. This records exact applicability.
CREATE TABLE MECANICA_ATRIBUTO (
    id_mecanica_sistema_atributo INTEGER NOT NULL REFERENCES MECANICA_SISTEMA_ATRIBUTO(id_mecanica_sistema_atributo) ON UPDATE RESTRICT ON DELETE CASCADE,
    id_atributo INTEGER NOT NULL REFERENCES ATRIBUTO_BATALHA(id_atributo) ON UPDATE RESTRICT ON DELETE RESTRICT,
    aplicabilidade TEXT NOT NULL CHECK(aplicabilidade IN ('aplicavel','nao_aplicavel','nao_verificado')),
    fonte_url TEXT,
    data_verificacao TEXT,
    PRIMARY KEY(id_mecanica_sistema_atributo,id_atributo),
    CHECK((fonte_url IS NULL)=(data_verificacao IS NULL)),
    CHECK(data_verificacao IS NULL OR (date(data_verificacao,'+0 days') IS NOT NULL AND date(data_verificacao,'+0 days')=data_verificacao)),
    CHECK(aplicabilidade='nao_verificado' OR (fonte_url IS NOT NULL AND length(trim(fonte_url))>0))
) STRICT;

CREATE TABLE POKEMON_COLECAO (
    id_pokemon_colecao INTEGER PRIMARY KEY,
    id_usuario INTEGER NOT NULL REFERENCES USUARIO(id_usuario) ON UPDATE RESTRICT ON DELETE CASCADE,
    id_dados_forma_atual INTEGER NOT NULL REFERENCES DADOS_FORMA_JOGO(id_dados_forma) ON UPDATE RESTRICT ON DELETE RESTRICT,
    id_mecanica INTEGER REFERENCES MECANICA_JOGO(id_mecanica) ON UPDATE RESTRICT ON DELETE RESTRICT,
    id_jogo_origem INTEGER REFERENCES JOGO(id_jogo) ON UPDATE RESTRICT ON DELETE RESTRICT,
    id_dados_forma_origem INTEGER REFERENCES DADOS_FORMA_JOGO(id_dados_forma) ON UPDATE RESTRICT ON DELETE RESTRICT,
    id_metodo_obtencao INTEGER REFERENCES METODO_OBTENCAO(id_metodo) ON UPDATE RESTRICT ON DELETE RESTRICT,
    id_natureza INTEGER REFERENCES NATUREZA(id_natureza) ON UPDATE RESTRICT ON DELETE RESTRICT,
    id_habilidade_forma INTEGER,
    apelido TEXT CHECK(length(apelido)<=40),
    nivel INTEGER CHECK(nivel>=0),
    data_registro TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    observacao TEXT CHECK(length(observacao)<=500),
    FOREIGN KEY(id_habilidade_forma,id_dados_forma_atual) REFERENCES HABILIDADE_FORMA_JOGO(id_habilidade_forma,id_dados_forma) ON UPDATE RESTRICT ON DELETE RESTRICT
) STRICT;

CREATE TABLE REGULAMENTO (
    id_regulamento INTEGER PRIMARY KEY,
    id_mecanica INTEGER NOT NULL REFERENCES MECANICA_JOGO(id_mecanica) ON UPDATE RESTRICT ON DELETE RESTRICT,
    codigo TEXT NOT NULL CHECK(length(trim(codigo))>0),
    versao TEXT NOT NULL CHECK(length(trim(versao))>0),
    nome TEXT NOT NULL CHECK(length(trim(nome))>0),
    formato TEXT NOT NULL CHECK(length(trim(formato))>0),
    temporada TEXT NOT NULL CHECK(length(trim(temporada))>0),
    data_inicio TEXT,
    data_fim TEXT,
    fonte_url TEXT NOT NULL CHECK(length(trim(fonte_url))>0),
    data_verificacao TEXT NOT NULL CHECK(date(data_verificacao,'+0 days') IS NOT NULL AND date(data_verificacao,'+0 days')=data_verificacao),
    UNIQUE(id_mecanica,codigo,versao,formato,temporada),
    CHECK(data_inicio IS NULL OR (date(data_inicio,'+0 days') IS NOT NULL AND date(data_inicio,'+0 days')=data_inicio)),
    CHECK(data_fim IS NULL OR (date(data_fim,'+0 days') IS NOT NULL AND date(data_fim,'+0 days')=data_fim)),
    CHECK(data_fim IS NULL OR data_inicio IS NULL OR data_fim>=data_inicio)
) STRICT;
CREATE TABLE PERFIL_ANALISE (
    id_perfil INTEGER PRIMARY KEY,
    id_dados_forma INTEGER NOT NULL REFERENCES DADOS_FORMA_JOGO(id_dados_forma) ON UPDATE RESTRICT ON DELETE RESTRICT,
    id_mecanica INTEGER NOT NULL REFERENCES MECANICA_JOGO(id_mecanica) ON UPDATE RESTRICT ON DELETE RESTRICT,
    id_usuario INTEGER REFERENCES USUARIO(id_usuario) ON UPDATE RESTRICT ON DELETE CASCADE,
    id_regulamento INTEGER REFERENCES REGULAMENTO(id_regulamento) ON UPDATE RESTRICT ON DELETE RESTRICT,
    nome_perfil TEXT NOT NULL CHECK(length(trim(nome_perfil))>0),
    descricao TEXT,
    tipo_perfil TEXT NOT NULL CHECK(tipo_perfil IN ('personalizado','referencia_competitiva')),
    fonte_url TEXT,
    data_verificacao TEXT,
    versao_fonte TEXT,
    CHECK((tipo_perfil='personalizado' AND id_usuario IS NOT NULL) OR (tipo_perfil='referencia_competitiva' AND id_usuario IS NULL)),
    CHECK((fonte_url IS NULL)=(data_verificacao IS NULL)),
    CHECK(data_verificacao IS NULL OR (date(data_verificacao,'+0 days') IS NOT NULL AND date(data_verificacao,'+0 days')=data_verificacao)),
    CHECK(tipo_perfil!='referencia_competitiva' OR (fonte_url IS NOT NULL AND length(trim(fonte_url))>0 AND versao_fonte IS NOT NULL AND length(trim(versao_fonte))>0))
) STRICT;
CREATE TABLE VALOR_ATRIBUTO_POKEMON (
    id_valor_atributo INTEGER PRIMARY KEY,
    id_pokemon_colecao INTEGER NOT NULL REFERENCES POKEMON_COLECAO(id_pokemon_colecao) ON UPDATE RESTRICT ON DELETE CASCADE,
    id_mecanica_sistema_atributo INTEGER NOT NULL REFERENCES MECANICA_SISTEMA_ATRIBUTO(id_mecanica_sistema_atributo) ON UPDATE RESTRICT ON DELETE RESTRICT,
    id_atributo INTEGER NOT NULL REFERENCES ATRIBUTO_BATALHA(id_atributo) ON UPDATE RESTRICT ON DELETE RESTRICT,
    estado TEXT NOT NULL DEFAULT 'conhecido' CHECK(estado IN ('conhecido','desconhecido','nao_aplicavel')),
    valor INTEGER,
    motivo TEXT,
    UNIQUE(id_pokemon_colecao,id_mecanica_sistema_atributo,id_atributo),
    CHECK((estado='conhecido' AND valor IS NOT NULL) OR (estado!='conhecido' AND valor IS NULL))
) STRICT;
CREATE TABLE VALOR_PERFIL_ANALISE (
    id_valor_perfil INTEGER PRIMARY KEY,
    id_perfil INTEGER NOT NULL REFERENCES PERFIL_ANALISE(id_perfil) ON UPDATE RESTRICT ON DELETE CASCADE,
    id_mecanica_sistema_atributo INTEGER NOT NULL REFERENCES MECANICA_SISTEMA_ATRIBUTO(id_mecanica_sistema_atributo) ON UPDATE RESTRICT ON DELETE RESTRICT,
    id_atributo INTEGER NOT NULL REFERENCES ATRIBUTO_BATALHA(id_atributo) ON UPDATE RESTRICT ON DELETE RESTRICT,
    estado TEXT NOT NULL DEFAULT 'conhecido' CHECK(estado IN ('conhecido','desconhecido','nao_aplicavel')),
    valor_alvo INTEGER,
    motivo TEXT,
    UNIQUE(id_perfil,id_mecanica_sistema_atributo,id_atributo),
    CHECK((estado='conhecido' AND valor_alvo IS NOT NULL) OR (estado!='conhecido' AND valor_alvo IS NULL))
) STRICT;
CREATE TABLE PERFIL_NATUREZA (
    id_perfil INTEGER NOT NULL REFERENCES PERFIL_ANALISE(id_perfil) ON UPDATE RESTRICT ON DELETE CASCADE,
    id_natureza INTEGER NOT NULL REFERENCES NATUREZA(id_natureza) ON UPDATE RESTRICT ON DELETE RESTRICT,
    PRIMARY KEY(id_perfil,id_natureza)
) STRICT;
CREATE TABLE PERFIL_HABILIDADE (
    id_perfil INTEGER NOT NULL REFERENCES PERFIL_ANALISE(id_perfil) ON UPDATE RESTRICT ON DELETE CASCADE,
    id_habilidade_forma INTEGER NOT NULL REFERENCES HABILIDADE_FORMA_JOGO(id_habilidade_forma) ON UPDATE RESTRICT ON DELETE RESTRICT,
    PRIMARY KEY(id_perfil,id_habilidade_forma)
) STRICT;
CREATE TABLE ELEGIBILIDADE_FORMA_REGULAMENTO (
    id_elegibilidade INTEGER PRIMARY KEY,
    id_regulamento INTEGER NOT NULL REFERENCES REGULAMENTO(id_regulamento) ON UPDATE RESTRICT ON DELETE RESTRICT,
    id_dados_forma INTEGER NOT NULL REFERENCES DADOS_FORMA_JOGO(id_dados_forma) ON UPDATE RESTRICT ON DELETE RESTRICT,
    status TEXT NOT NULL DEFAULT 'nao_verificado' CHECK(status IN ('permitido','restrito','proibido','condicional','nao_verificado')),
    condicao TEXT,
    fonte_url TEXT,
    data_verificacao TEXT,
    UNIQUE(id_regulamento,id_dados_forma),
    CHECK((fonte_url IS NULL)=(data_verificacao IS NULL)),
    CHECK(data_verificacao IS NULL OR (date(data_verificacao,'+0 days') IS NOT NULL AND date(data_verificacao,'+0 days')=data_verificacao)),
    CHECK(status='nao_verificado' OR (fonte_url IS NOT NULL AND length(trim(fonte_url))>0)),
    CHECK(status NOT IN ('restrito','condicional') OR (condicao IS NOT NULL AND length(trim(condicao))>0))
) STRICT;
CREATE TABLE TRANSFORMACAO_FORMA (
    id_transformacao INTEGER PRIMARY KEY,
    id_dados_forma_origem INTEGER NOT NULL REFERENCES DADOS_FORMA_JOGO(id_dados_forma) ON UPDATE RESTRICT ON DELETE RESTRICT,
    id_dados_forma_destino INTEGER NOT NULL REFERENCES DADOS_FORMA_JOGO(id_dados_forma) ON UPDATE RESTRICT ON DELETE RESTRICT,
    tipo_transformacao TEXT NOT NULL CHECK(length(trim(tipo_transformacao))>0),
    temporaria INTEGER NOT NULL CHECK(temporaria IN (0,1)),
    condicao TEXT NOT NULL CHECK(length(trim(condicao))>0),
    item_requerido TEXT,
    observacao TEXT,
    fonte_url TEXT NOT NULL CHECK(length(trim(fonte_url))>0),
    data_verificacao TEXT NOT NULL CHECK(date(data_verificacao,'+0 days') IS NOT NULL AND date(data_verificacao,'+0 days')=data_verificacao),
    UNIQUE(id_dados_forma_origem,id_dados_forma_destino,tipo_transformacao,condicao),
    CHECK(id_dados_forma_origem!=id_dados_forma_destino)
) STRICT;

CREATE INDEX ix_especie_nome_pt ON ESPECIE(nome_pt COLLATE NOCASE);
CREATE INDEX ix_especie_geracao ON ESPECIE(geracao_origem);
CREATE INDEX ix_forma_especie ON FORMA(id_especie);
CREATE INDEX ix_dados_forma_jogo ON DADOS_FORMA_JOGO(id_jogo,id_forma);
CREATE INDEX ix_tipo_contexto ON TIPO_FORMA_JOGO(id_tipo,id_dados_forma);
CREATE INDEX ix_colecao_usuario ON POKEMON_COLECAO(id_usuario,id_pokemon_colecao);
CREATE INDEX ix_colecao_contexto ON POKEMON_COLECAO(id_dados_forma_atual);
CREATE INDEX ix_colecao_mecanica ON POKEMON_COLECAO(id_mecanica);
CREATE INDEX ix_perfil_usuario ON PERFIL_ANALISE(id_usuario,id_perfil);
CREATE INDEX ix_perfil_contexto ON PERFIL_ANALISE(id_dados_forma,id_mecanica);
CREATE INDEX ix_elegibilidade_contexto ON ELEGIBILIDADE_FORMA_REGULAMENTO(id_dados_forma);

CREATE TRIGGER especie_completa_insert BEFORE INSERT ON ESPECIE
BEGIN
    SELECT CASE WHEN NEW.status_catalogo = 'completo' AND (SELECT count(*) FROM FORMA WHERE id_especie=NEW.id_especie AND forma_padrao=1) != 1 THEN RAISE(ABORT, 'Especie completa exige exatamente uma forma padrao') END;
END;

CREATE TRIGGER especie_completa_update BEFORE UPDATE ON ESPECIE
BEGIN
    SELECT CASE WHEN NEW.status_catalogo = 'completo' AND (SELECT count(*) FROM FORMA WHERE id_especie=NEW.id_especie AND forma_padrao=1) != 1 THEN RAISE(ABORT, 'Especie completa exige exatamente uma forma padrao') END;
END;

CREATE TRIGGER forma_padrao_preservada_update BEFORE UPDATE ON FORMA
BEGIN
    SELECT CASE WHEN EXISTS (SELECT 1 FROM ESPECIE WHERE id_especie=OLD.id_especie AND status_catalogo='completo') AND OLD.forma_padrao=1 AND (NEW.forma_padrao!=1 OR NEW.id_especie!=OLD.id_especie) THEN RAISE(ABORT, 'Forma padrao de especie completa deve ser preservada') END;
END;

CREATE TRIGGER forma_padrao_preservada_delete BEFORE DELETE ON FORMA
BEGIN
    SELECT CASE WHEN OLD.forma_padrao=1 AND EXISTS (SELECT 1 FROM ESPECIE WHERE id_especie=OLD.id_especie AND status_catalogo='completo') THEN RAISE(ABORT, 'Forma padrao de especie completa deve ser preservada') END;
END;

CREATE TRIGGER forma_padrao_preservada_replace BEFORE INSERT ON FORMA
BEGIN
    SELECT CASE WHEN EXISTS (SELECT 1 FROM FORMA f JOIN ESPECIE e ON e.id_especie=f.id_especie WHERE f.forma_padrao=1 AND e.status_catalogo='completo' AND (f.id_forma=NEW.id_forma OR (f.id_especie=NEW.id_especie AND (f.codigo_forma=NEW.codigo_forma OR NEW.forma_padrao=1)))) THEN RAISE(ABORT, 'Substituicao implicita da forma padrao nao permitida') END;
END;

CREATE TRIGGER tipos_confirmados_insert BEFORE INSERT ON DADOS_FORMA_JOGO
BEGIN
    SELECT CASE WHEN NEW.status_tipos='aplicavel' AND NOT EXISTS (SELECT 1 FROM TIPO_FORMA_JOGO WHERE id_dados_forma=NEW.id_dados_forma AND posicao=1) THEN RAISE(ABORT, 'Tipos aplicaveis exigem tipo primario') END;
    SELECT CASE WHEN NEW.status_tipos='nao_aplicavel' AND EXISTS (SELECT 1 FROM TIPO_FORMA_JOGO WHERE id_dados_forma=NEW.id_dados_forma) THEN RAISE(ABORT, 'Contexto sem tipos nao admite tipos') END;
END;

CREATE TRIGGER tipos_confirmados_update BEFORE UPDATE ON DADOS_FORMA_JOGO
BEGIN
    SELECT CASE WHEN NEW.status_tipos='aplicavel' AND NOT EXISTS (SELECT 1 FROM TIPO_FORMA_JOGO WHERE id_dados_forma=NEW.id_dados_forma AND posicao=1) THEN RAISE(ABORT, 'Tipos aplicaveis exigem tipo primario') END;
    SELECT CASE WHEN NEW.status_tipos='nao_aplicavel' AND EXISTS (SELECT 1 FROM TIPO_FORMA_JOGO WHERE id_dados_forma=NEW.id_dados_forma) THEN RAISE(ABORT, 'Contexto sem tipos nao admite tipos') END;
END;

CREATE TRIGGER tipo_aplicavel_insert BEFORE INSERT ON TIPO_FORMA_JOGO
BEGIN
    SELECT CASE WHEN EXISTS (SELECT 1 FROM DADOS_FORMA_JOGO WHERE id_dados_forma=NEW.id_dados_forma AND status_tipos='nao_aplicavel') THEN RAISE(ABORT, 'Tipos nao aplicaveis ao contexto') END;
END;

CREATE TRIGGER tipo_aplicavel_update BEFORE UPDATE ON TIPO_FORMA_JOGO
BEGIN
    SELECT CASE WHEN EXISTS (SELECT 1 FROM DADOS_FORMA_JOGO WHERE id_dados_forma=NEW.id_dados_forma AND status_tipos='nao_aplicavel') THEN RAISE(ABORT, 'Tipos nao aplicaveis ao contexto') END;
END;

CREATE TRIGGER cobertura_tipo_delete AFTER DELETE ON TIPO_FORMA_JOGO
BEGIN
    SELECT CASE WHEN EXISTS (SELECT 1 FROM DADOS_FORMA_JOGO WHERE id_dados_forma=OLD.id_dados_forma AND status_tipos='aplicavel') AND NOT EXISTS (SELECT 1 FROM TIPO_FORMA_JOGO WHERE id_dados_forma=OLD.id_dados_forma AND posicao=1) THEN RAISE(ABORT, 'Remocao invalidaria cobertura de tipos') END;
END;

CREATE TRIGGER cobertura_tipo_update AFTER UPDATE ON TIPO_FORMA_JOGO
BEGIN
    SELECT CASE WHEN EXISTS (SELECT 1 FROM DADOS_FORMA_JOGO WHERE id_dados_forma=OLD.id_dados_forma AND status_tipos='aplicavel') AND NOT EXISTS (SELECT 1 FROM TIPO_FORMA_JOGO WHERE id_dados_forma=OLD.id_dados_forma AND posicao=1) THEN RAISE(ABORT, 'Remocao invalidaria cobertura de tipos') END;
END;

CREATE TRIGGER cobertura_tipo_insert AFTER INSERT ON TIPO_FORMA_JOGO
BEGIN
    SELECT CASE WHEN EXISTS (SELECT 1 FROM DADOS_FORMA_JOGO WHERE id_dados_forma=NEW.id_dados_forma AND status_tipos='aplicavel') AND NOT EXISTS (SELECT 1 FROM TIPO_FORMA_JOGO WHERE id_dados_forma=NEW.id_dados_forma AND posicao=1) THEN RAISE(ABORT, 'Substituicao invalidaria cobertura de tipos') END;
END;

CREATE TRIGGER preservar_dados_forma_jogo BEFORE UPDATE ON DADOS_FORMA_JOGO
BEGIN
    SELECT CASE WHEN (NEW.id_forma IS NOT OLD.id_forma OR NEW.id_jogo IS NOT OLD.id_jogo OR NEW.status_presenca IS NOT OLD.status_presenca OR NEW.pode_ser_registrada IS NOT OLD.pode_ser_registrada) AND (EXISTS (SELECT 1 FROM POKEMON_COLECAO WHERE id_dados_forma_atual=OLD.id_dados_forma) OR EXISTS (SELECT 1 FROM POKEMON_COLECAO WHERE id_dados_forma_origem=OLD.id_dados_forma) OR EXISTS (SELECT 1 FROM PERFIL_ANALISE WHERE id_dados_forma=OLD.id_dados_forma) OR EXISTS (SELECT 1 FROM ELEGIBILIDADE_FORMA_REGULAMENTO WHERE id_dados_forma=OLD.id_dados_forma) OR EXISTS (SELECT 1 FROM TRANSFORMACAO_FORMA WHERE id_dados_forma_origem=OLD.id_dados_forma) OR EXISTS (SELECT 1 FROM TRANSFORMACAO_FORMA WHERE id_dados_forma_destino=OLD.id_dados_forma)) THEN RAISE(ABORT, 'Registro utilizado: crie nova versao ou remova dependencias em transacao') END;
END;

CREATE TRIGGER preservar_mecanica_jogo BEFORE UPDATE ON MECANICA_JOGO
BEGIN
    SELECT CASE WHEN (NEW.id_jogo IS NOT OLD.id_jogo OR NEW.versao IS NOT OLD.versao OR NEW.usa_natureza IS NOT OLD.usa_natureza OR NEW.usa_habilidade IS NOT OLD.usa_habilidade OR NEW.usa_nivel IS NOT OLD.usa_nivel OR NEW.nivel_minimo IS NOT OLD.nivel_minimo OR NEW.nivel_maximo IS NOT OLD.nivel_maximo) AND (EXISTS (SELECT 1 FROM POKEMON_COLECAO WHERE id_mecanica=OLD.id_mecanica) OR EXISTS (SELECT 1 FROM PERFIL_ANALISE WHERE id_mecanica=OLD.id_mecanica) OR EXISTS (SELECT 1 FROM REGULAMENTO WHERE id_mecanica=OLD.id_mecanica) OR EXISTS (SELECT 1 FROM MECANICA_SISTEMA_ATRIBUTO WHERE id_mecanica=OLD.id_mecanica)) THEN RAISE(ABORT, 'Registro utilizado: crie nova versao ou remova dependencias em transacao') END;
END;

CREATE TRIGGER preservar_mecanica_sistema_atributo BEFORE UPDATE ON MECANICA_SISTEMA_ATRIBUTO
BEGIN
    SELECT CASE WHEN (NEW.id_mecanica IS NOT OLD.id_mecanica OR NEW.id_sistema_atributo IS NOT OLD.id_sistema_atributo OR NEW.aplicabilidade IS NOT OLD.aplicabilidade OR NEW.unidade IS NOT OLD.unidade OR NEW.valor_minimo IS NOT OLD.valor_minimo OR NEW.valor_maximo_atributo IS NOT OLD.valor_maximo_atributo OR NEW.valor_maximo_total IS NOT OLD.valor_maximo_total OR NEW.limite_total_status IS NOT OLD.limite_total_status) AND (EXISTS (SELECT 1 FROM VALOR_ATRIBUTO_POKEMON WHERE id_mecanica_sistema_atributo=OLD.id_mecanica_sistema_atributo) OR EXISTS (SELECT 1 FROM VALOR_PERFIL_ANALISE WHERE id_mecanica_sistema_atributo=OLD.id_mecanica_sistema_atributo)) THEN RAISE(ABORT, 'Registro utilizado: crie nova versao ou remova dependencias em transacao') END;
END;

CREATE TRIGGER preservar_regulamento BEFORE UPDATE ON REGULAMENTO
BEGIN
    SELECT CASE WHEN (NEW.id_mecanica IS NOT OLD.id_mecanica OR NEW.codigo IS NOT OLD.codigo OR NEW.versao IS NOT OLD.versao OR NEW.formato IS NOT OLD.formato OR NEW.temporada IS NOT OLD.temporada) AND (EXISTS (SELECT 1 FROM PERFIL_ANALISE WHERE id_regulamento=OLD.id_regulamento) OR EXISTS (SELECT 1 FROM ELEGIBILIDADE_FORMA_REGULAMENTO WHERE id_regulamento=OLD.id_regulamento)) THEN RAISE(ABORT, 'Registro utilizado: crie nova versao ou remova dependencias em transacao') END;
END;

CREATE TRIGGER colecao_contexto_insert BEFORE INSERT ON POKEMON_COLECAO
BEGIN
    SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM DADOS_FORMA_JOGO WHERE id_dados_forma=NEW.id_dados_forma_atual AND status_presenca IN ('nativa','transferivel') AND pode_ser_registrada='sim') THEN RAISE(ABORT, 'Contexto atual exige presenca e registro independente confirmados') END;
    SELECT CASE WHEN NEW.id_mecanica IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MECANICA_JOGO m JOIN DADOS_FORMA_JOGO d ON d.id_jogo=m.id_jogo WHERE m.id_mecanica=NEW.id_mecanica AND d.id_dados_forma=NEW.id_dados_forma_atual) THEN RAISE(ABORT, 'Mecanica e contexto atual pertencem a jogos distintos') END;
    SELECT CASE WHEN NEW.id_natureza IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MECANICA_JOGO WHERE id_mecanica=NEW.id_mecanica AND usa_natureza='sim') THEN RAISE(ABORT, 'Valor exige aplicabilidade confirmada: id_natureza') END;
    SELECT CASE WHEN NEW.id_habilidade_forma IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MECANICA_JOGO WHERE id_mecanica=NEW.id_mecanica AND usa_habilidade='sim') THEN RAISE(ABORT, 'Valor exige aplicabilidade confirmada: id_habilidade_forma') END;
    SELECT CASE WHEN NEW.nivel IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MECANICA_JOGO WHERE id_mecanica=NEW.id_mecanica AND usa_nivel='sim') THEN RAISE(ABORT, 'Valor exige aplicabilidade confirmada: nivel') END;
    SELECT CASE WHEN NEW.nivel IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MECANICA_JOGO WHERE id_mecanica=NEW.id_mecanica AND nivel_minimo IS NOT NULL AND nivel_maximo IS NOT NULL AND NEW.nivel BETWEEN nivel_minimo AND nivel_maximo) THEN RAISE(ABORT, 'Nivel fora dos limites confirmados') END;
    SELECT CASE WHEN NEW.id_habilidade_forma IS NOT NULL AND NOT EXISTS (SELECT 1 FROM HABILIDADE_FORMA_JOGO WHERE id_habilidade_forma=NEW.id_habilidade_forma AND id_dados_forma=NEW.id_dados_forma_atual) THEN RAISE(ABORT, 'Habilidade incompativel com contexto atual') END;
    SELECT CASE WHEN NEW.id_dados_forma_origem IS NOT NULL AND (NEW.id_jogo_origem IS NULL OR NOT EXISTS (SELECT 1 FROM DADOS_FORMA_JOGO WHERE id_dados_forma=NEW.id_dados_forma_origem AND id_jogo=NEW.id_jogo_origem)) THEN RAISE(ABORT, 'Forma de origem exige jogo de origem compativel') END;
END;

CREATE TRIGGER colecao_contexto_update BEFORE UPDATE ON POKEMON_COLECAO
BEGIN
    SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM DADOS_FORMA_JOGO WHERE id_dados_forma=NEW.id_dados_forma_atual AND status_presenca IN ('nativa','transferivel') AND pode_ser_registrada='sim') THEN RAISE(ABORT, 'Contexto atual exige presenca e registro independente confirmados') END;
    SELECT CASE WHEN NEW.id_mecanica IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MECANICA_JOGO m JOIN DADOS_FORMA_JOGO d ON d.id_jogo=m.id_jogo WHERE m.id_mecanica=NEW.id_mecanica AND d.id_dados_forma=NEW.id_dados_forma_atual) THEN RAISE(ABORT, 'Mecanica e contexto atual pertencem a jogos distintos') END;
    SELECT CASE WHEN NEW.id_natureza IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MECANICA_JOGO WHERE id_mecanica=NEW.id_mecanica AND usa_natureza='sim') THEN RAISE(ABORT, 'Valor exige aplicabilidade confirmada: id_natureza') END;
    SELECT CASE WHEN NEW.id_habilidade_forma IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MECANICA_JOGO WHERE id_mecanica=NEW.id_mecanica AND usa_habilidade='sim') THEN RAISE(ABORT, 'Valor exige aplicabilidade confirmada: id_habilidade_forma') END;
    SELECT CASE WHEN NEW.nivel IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MECANICA_JOGO WHERE id_mecanica=NEW.id_mecanica AND usa_nivel='sim') THEN RAISE(ABORT, 'Valor exige aplicabilidade confirmada: nivel') END;
    SELECT CASE WHEN NEW.nivel IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MECANICA_JOGO WHERE id_mecanica=NEW.id_mecanica AND nivel_minimo IS NOT NULL AND nivel_maximo IS NOT NULL AND NEW.nivel BETWEEN nivel_minimo AND nivel_maximo) THEN RAISE(ABORT, 'Nivel fora dos limites confirmados') END;
    SELECT CASE WHEN NEW.id_habilidade_forma IS NOT NULL AND NOT EXISTS (SELECT 1 FROM HABILIDADE_FORMA_JOGO WHERE id_habilidade_forma=NEW.id_habilidade_forma AND id_dados_forma=NEW.id_dados_forma_atual) THEN RAISE(ABORT, 'Habilidade incompativel com contexto atual') END;
    SELECT CASE WHEN NEW.id_dados_forma_origem IS NOT NULL AND (NEW.id_jogo_origem IS NULL OR NOT EXISTS (SELECT 1 FROM DADOS_FORMA_JOGO WHERE id_dados_forma=NEW.id_dados_forma_origem AND id_jogo=NEW.id_jogo_origem)) THEN RAISE(ABORT, 'Forma de origem exige jogo de origem compativel') END;
END;

CREATE TRIGGER colecao_preservar_contexto BEFORE UPDATE ON POKEMON_COLECAO
BEGIN
    SELECT CASE WHEN (NEW.id_dados_forma_atual IS NOT OLD.id_dados_forma_atual OR NEW.id_mecanica IS NOT OLD.id_mecanica) AND EXISTS (SELECT 1 FROM VALOR_ATRIBUTO_POKEMON WHERE id_pokemon_colecao=OLD.id_pokemon_colecao) THEN RAISE(ABORT, 'Remova valores do contexto anterior em transacao antes de mudar contexto') END;
END;

CREATE TRIGGER perfil_contexto_insert BEFORE INSERT ON PERFIL_ANALISE
BEGIN
    SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM DADOS_FORMA_JOGO d JOIN MECANICA_JOGO m ON m.id_jogo=d.id_jogo WHERE d.id_dados_forma=NEW.id_dados_forma AND m.id_mecanica=NEW.id_mecanica) THEN RAISE(ABORT, 'Perfil: forma e mecanica de jogos distintos') END;
    SELECT CASE WHEN NEW.id_regulamento IS NOT NULL AND NOT EXISTS (SELECT 1 FROM REGULAMENTO WHERE id_regulamento=NEW.id_regulamento AND id_mecanica=NEW.id_mecanica) THEN RAISE(ABORT, 'Perfil e regulamento de mecanicas distintas') END;
END;

CREATE TRIGGER perfil_contexto_update BEFORE UPDATE ON PERFIL_ANALISE
BEGIN
    SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM DADOS_FORMA_JOGO d JOIN MECANICA_JOGO m ON m.id_jogo=d.id_jogo WHERE d.id_dados_forma=NEW.id_dados_forma AND m.id_mecanica=NEW.id_mecanica) THEN RAISE(ABORT, 'Perfil: forma e mecanica de jogos distintos') END;
    SELECT CASE WHEN NEW.id_regulamento IS NOT NULL AND NOT EXISTS (SELECT 1 FROM REGULAMENTO WHERE id_regulamento=NEW.id_regulamento AND id_mecanica=NEW.id_mecanica) THEN RAISE(ABORT, 'Perfil e regulamento de mecanicas distintas') END;
END;

CREATE TRIGGER perfil_preservar_contexto BEFORE UPDATE ON PERFIL_ANALISE
BEGIN
    SELECT CASE WHEN (NEW.id_dados_forma IS NOT OLD.id_dados_forma OR NEW.id_mecanica IS NOT OLD.id_mecanica) AND (EXISTS (SELECT 1 FROM VALOR_PERFIL_ANALISE WHERE id_perfil=OLD.id_perfil) OR EXISTS (SELECT 1 FROM PERFIL_NATUREZA WHERE id_perfil=OLD.id_perfil) OR EXISTS (SELECT 1 FROM PERFIL_HABILIDADE WHERE id_perfil=OLD.id_perfil)) THEN RAISE(ABORT, 'Perfil utilizado exige revisao das opcoes antes de mudar contexto') END;
END;

CREATE TRIGGER perfil_natureza_compativel_insert BEFORE INSERT ON PERFIL_NATUREZA
BEGIN
    SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM PERFIL_ANALISE p JOIN MECANICA_JOGO m ON m.id_mecanica=p.id_mecanica WHERE p.id_perfil=NEW.id_perfil AND m.usa_natureza='sim') THEN RAISE(ABORT, 'Natureza nao confirmada para perfil') END;
END;

CREATE TRIGGER perfil_natureza_compativel_update BEFORE UPDATE ON PERFIL_NATUREZA
BEGIN
    SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM PERFIL_ANALISE p JOIN MECANICA_JOGO m ON m.id_mecanica=p.id_mecanica WHERE p.id_perfil=NEW.id_perfil AND m.usa_natureza='sim') THEN RAISE(ABORT, 'Natureza nao confirmada para perfil') END;
END;

CREATE TRIGGER perfil_habilidade_compativel_insert BEFORE INSERT ON PERFIL_HABILIDADE
BEGIN
    SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM PERFIL_ANALISE p JOIN HABILIDADE_FORMA_JOGO h ON h.id_dados_forma=p.id_dados_forma JOIN MECANICA_JOGO m ON m.id_mecanica=p.id_mecanica WHERE p.id_perfil=NEW.id_perfil AND h.id_habilidade_forma=NEW.id_habilidade_forma AND m.usa_habilidade='sim') THEN RAISE(ABORT, 'Habilidade incompativel com perfil') END;
END;

CREATE TRIGGER perfil_habilidade_compativel_update BEFORE UPDATE ON PERFIL_HABILIDADE
BEGIN
    SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM PERFIL_ANALISE p JOIN HABILIDADE_FORMA_JOGO h ON h.id_dados_forma=p.id_dados_forma JOIN MECANICA_JOGO m ON m.id_mecanica=p.id_mecanica WHERE p.id_perfil=NEW.id_perfil AND h.id_habilidade_forma=NEW.id_habilidade_forma AND m.usa_habilidade='sim') THEN RAISE(ABORT, 'Habilidade incompativel com perfil') END;
END;

CREATE TRIGGER habilidade_contexto_imutavel BEFORE UPDATE ON HABILIDADE_FORMA_JOGO
BEGIN
    SELECT CASE WHEN (NEW.id_dados_forma IS NOT OLD.id_dados_forma OR NEW.id_habilidade IS NOT OLD.id_habilidade OR NEW.slot IS NOT OLD.slot) AND (EXISTS (SELECT 1 FROM POKEMON_COLECAO WHERE id_habilidade_forma=OLD.id_habilidade_forma) OR EXISTS (SELECT 1 FROM PERFIL_HABILIDADE WHERE id_habilidade_forma=OLD.id_habilidade_forma)) THEN RAISE(ABORT, 'Habilidade utilizada nao pode mudar de identidade') END;
END;

CREATE TRIGGER elegibilidade_contexto_insert BEFORE INSERT ON ELEGIBILIDADE_FORMA_REGULAMENTO
BEGIN
    SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM REGULAMENTO r JOIN MECANICA_JOGO m ON m.id_mecanica=r.id_mecanica JOIN DADOS_FORMA_JOGO d ON d.id_jogo=m.id_jogo WHERE r.id_regulamento=NEW.id_regulamento AND d.id_dados_forma=NEW.id_dados_forma) THEN RAISE(ABORT, 'Elegibilidade de jogo incompativel') END;
END;

CREATE TRIGGER elegibilidade_contexto_update BEFORE UPDATE ON ELEGIBILIDADE_FORMA_REGULAMENTO
BEGIN
    SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM REGULAMENTO r JOIN MECANICA_JOGO m ON m.id_mecanica=r.id_mecanica JOIN DADOS_FORMA_JOGO d ON d.id_jogo=m.id_jogo WHERE r.id_regulamento=NEW.id_regulamento AND d.id_dados_forma=NEW.id_dados_forma) THEN RAISE(ABORT, 'Elegibilidade de jogo incompativel') END;
END;

CREATE TRIGGER transformacao_contexto_insert BEFORE INSERT ON TRANSFORMACAO_FORMA
BEGIN
    SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM DADOS_FORMA_JOGO a JOIN DADOS_FORMA_JOGO b ON b.id_jogo=a.id_jogo WHERE a.id_dados_forma=NEW.id_dados_forma_origem AND b.id_dados_forma=NEW.id_dados_forma_destino) THEN RAISE(ABORT, 'Transformacao exige endpoints do mesmo jogo') END;
END;

CREATE TRIGGER transformacao_contexto_update BEFORE UPDATE ON TRANSFORMACAO_FORMA
BEGIN
    SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM DADOS_FORMA_JOGO a JOIN DADOS_FORMA_JOGO b ON b.id_jogo=a.id_jogo WHERE a.id_dados_forma=NEW.id_dados_forma_origem AND b.id_dados_forma=NEW.id_dados_forma_destino) THEN RAISE(ABORT, 'Transformacao exige endpoints do mesmo jogo') END;
END;

CREATE TRIGGER valor_atributo_pokemon_insert BEFORE INSERT ON VALOR_ATRIBUTO_POKEMON
BEGIN
    SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM POKEMON_COLECAO o JOIN MECANICA_SISTEMA_ATRIBUTO s ON s.id_mecanica=o.id_mecanica WHERE o.id_pokemon_colecao=NEW.id_pokemon_colecao AND s.id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo) THEN RAISE(ABORT, 'Valor e proprietario de mecanicas distintas') END;
    SELECT CASE WHEN NEW.estado='conhecido' AND NOT EXISTS (SELECT 1 FROM MECANICA_SISTEMA_ATRIBUTO s JOIN MECANICA_ATRIBUTO a USING(id_mecanica_sistema_atributo) WHERE s.id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo AND a.id_atributo=NEW.id_atributo AND s.aplicabilidade='aplicavel' AND a.aplicabilidade='aplicavel' AND s.valor_minimo IS NOT NULL AND s.valor_maximo_atributo IS NOT NULL AND s.limite_total_status!='nao_verificado' AND NEW.valor BETWEEN s.valor_minimo AND s.valor_maximo_atributo) THEN RAISE(ABORT, 'Valor exige aplicabilidade e limites confirmados') END;
    SELECT CASE WHEN NEW.estado='nao_aplicavel' AND NOT EXISTS (SELECT 1 FROM MECANICA_SISTEMA_ATRIBUTO s LEFT JOIN MECANICA_ATRIBUTO a ON a.id_mecanica_sistema_atributo=s.id_mecanica_sistema_atributo AND a.id_atributo=NEW.id_atributo WHERE s.id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo AND (s.aplicabilidade='nao_aplicavel' OR a.aplicabilidade='nao_aplicavel')) THEN RAISE(ABORT, 'Inaplicabilidade deve ser confirmada') END;
    SELECT CASE WHEN NEW.estado='conhecido' AND NEW.valor + COALESCE((SELECT sum(v.valor) FROM VALOR_ATRIBUTO_POKEMON v WHERE v.id_pokemon_colecao=NEW.id_pokemon_colecao AND v.id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo AND v.estado='conhecido'),0) > (SELECT valor_maximo_total FROM MECANICA_SISTEMA_ATRIBUTO WHERE id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo AND limite_total_status='confirmado') THEN RAISE(ABORT, 'Soma ultrapassa limite combinado confirmado') END;
END;

CREATE TRIGGER valor_atributo_pokemon_update BEFORE UPDATE ON VALOR_ATRIBUTO_POKEMON
BEGIN
    SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM POKEMON_COLECAO o JOIN MECANICA_SISTEMA_ATRIBUTO s ON s.id_mecanica=o.id_mecanica WHERE o.id_pokemon_colecao=NEW.id_pokemon_colecao AND s.id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo) THEN RAISE(ABORT, 'Valor e proprietario de mecanicas distintas') END;
    SELECT CASE WHEN NEW.estado='conhecido' AND NOT EXISTS (SELECT 1 FROM MECANICA_SISTEMA_ATRIBUTO s JOIN MECANICA_ATRIBUTO a USING(id_mecanica_sistema_atributo) WHERE s.id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo AND a.id_atributo=NEW.id_atributo AND s.aplicabilidade='aplicavel' AND a.aplicabilidade='aplicavel' AND s.valor_minimo IS NOT NULL AND s.valor_maximo_atributo IS NOT NULL AND s.limite_total_status!='nao_verificado' AND NEW.valor BETWEEN s.valor_minimo AND s.valor_maximo_atributo) THEN RAISE(ABORT, 'Valor exige aplicabilidade e limites confirmados') END;
    SELECT CASE WHEN NEW.estado='nao_aplicavel' AND NOT EXISTS (SELECT 1 FROM MECANICA_SISTEMA_ATRIBUTO s LEFT JOIN MECANICA_ATRIBUTO a ON a.id_mecanica_sistema_atributo=s.id_mecanica_sistema_atributo AND a.id_atributo=NEW.id_atributo WHERE s.id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo AND (s.aplicabilidade='nao_aplicavel' OR a.aplicabilidade='nao_aplicavel')) THEN RAISE(ABORT, 'Inaplicabilidade deve ser confirmada') END;
    SELECT CASE WHEN NEW.estado='conhecido' AND NEW.valor + COALESCE((SELECT sum(v.valor) FROM VALOR_ATRIBUTO_POKEMON v WHERE v.id_pokemon_colecao=NEW.id_pokemon_colecao AND v.id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo AND v.estado='conhecido' AND v.id_valor_atributo!=OLD.id_valor_atributo),0) > (SELECT valor_maximo_total FROM MECANICA_SISTEMA_ATRIBUTO WHERE id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo AND limite_total_status='confirmado') THEN RAISE(ABORT, 'Soma ultrapassa limite combinado confirmado') END;
END;

CREATE TRIGGER valor_perfil_analise_insert BEFORE INSERT ON VALOR_PERFIL_ANALISE
BEGIN
    SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM PERFIL_ANALISE o JOIN MECANICA_SISTEMA_ATRIBUTO s ON s.id_mecanica=o.id_mecanica WHERE o.id_perfil=NEW.id_perfil AND s.id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo) THEN RAISE(ABORT, 'Valor e proprietario de mecanicas distintas') END;
    SELECT CASE WHEN NEW.estado='conhecido' AND NOT EXISTS (SELECT 1 FROM MECANICA_SISTEMA_ATRIBUTO s JOIN MECANICA_ATRIBUTO a USING(id_mecanica_sistema_atributo) WHERE s.id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo AND a.id_atributo=NEW.id_atributo AND s.aplicabilidade='aplicavel' AND a.aplicabilidade='aplicavel' AND s.valor_minimo IS NOT NULL AND s.valor_maximo_atributo IS NOT NULL AND s.limite_total_status!='nao_verificado' AND NEW.valor_alvo BETWEEN s.valor_minimo AND s.valor_maximo_atributo) THEN RAISE(ABORT, 'Valor exige aplicabilidade e limites confirmados') END;
    SELECT CASE WHEN NEW.estado='nao_aplicavel' AND NOT EXISTS (SELECT 1 FROM MECANICA_SISTEMA_ATRIBUTO s LEFT JOIN MECANICA_ATRIBUTO a ON a.id_mecanica_sistema_atributo=s.id_mecanica_sistema_atributo AND a.id_atributo=NEW.id_atributo WHERE s.id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo AND (s.aplicabilidade='nao_aplicavel' OR a.aplicabilidade='nao_aplicavel')) THEN RAISE(ABORT, 'Inaplicabilidade deve ser confirmada') END;
    SELECT CASE WHEN NEW.estado='conhecido' AND NEW.valor_alvo + COALESCE((SELECT sum(v.valor_alvo) FROM VALOR_PERFIL_ANALISE v WHERE v.id_perfil=NEW.id_perfil AND v.id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo AND v.estado='conhecido'),0) > (SELECT valor_maximo_total FROM MECANICA_SISTEMA_ATRIBUTO WHERE id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo AND limite_total_status='confirmado') THEN RAISE(ABORT, 'Soma ultrapassa limite combinado confirmado') END;
END;

CREATE TRIGGER valor_perfil_analise_update BEFORE UPDATE ON VALOR_PERFIL_ANALISE
BEGIN
    SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM PERFIL_ANALISE o JOIN MECANICA_SISTEMA_ATRIBUTO s ON s.id_mecanica=o.id_mecanica WHERE o.id_perfil=NEW.id_perfil AND s.id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo) THEN RAISE(ABORT, 'Valor e proprietario de mecanicas distintas') END;
