    SELECT CASE WHEN NEW.estado='nao_aplicavel' AND NOT EXISTS (SELECT 1 FROM MECANICA_SISTEMA_ATRIBUTO s LEFT JOIN MECANICA_ATRIBUTO a ON a.id_mecanica_sistema_atributo=s.id_mecanica_sistema_atributo AND a.id_atributo=NEW.id_atributo WHERE s.id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo AND (s.aplicabilidade='nao_aplicavel' OR a.aplicabilidade='nao_aplicavel')) THEN RAISE(ABORT, 'Inaplicabilidade deve ser confirmada') END;
    SELECT CASE WHEN NEW.estado='conhecido' AND NEW.valor_alvo + COALESCE((SELECT sum(v.valor_alvo) FROM VALOR_PERFIL_ANALISE v WHERE v.id_perfil=NEW.id_perfil AND v.id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo AND v.estado='conhecido' AND v.id_valor_perfil!=OLD.id_valor_perfil),0) > (SELECT valor_maximo_total FROM MECANICA_SISTEMA_ATRIBUTO WHERE id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo AND limite_total_status='confirmado') THEN RAISE(ABORT, 'Soma ultrapassa limite combinado confirmado') END;
END;

CREATE TRIGGER mecanica_atributo_preservada_update BEFORE UPDATE ON MECANICA_ATRIBUTO
BEGIN
    SELECT CASE WHEN EXISTS (SELECT 1 FROM VALOR_ATRIBUTO_POKEMON WHERE id_mecanica_sistema_atributo=OLD.id_mecanica_sistema_atributo AND id_atributo=OLD.id_atributo) OR EXISTS (SELECT 1 FROM VALOR_PERFIL_ANALISE WHERE id_mecanica_sistema_atributo=OLD.id_mecanica_sistema_atributo AND id_atributo=OLD.id_atributo) THEN RAISE(ABORT, 'Aplicabilidade utilizada: crie nova versao') END;
END;

CREATE TRIGGER mecanica_atributo_preservada_delete BEFORE DELETE ON MECANICA_ATRIBUTO
BEGIN
    SELECT CASE WHEN EXISTS (SELECT 1 FROM VALOR_ATRIBUTO_POKEMON WHERE id_mecanica_sistema_atributo=OLD.id_mecanica_sistema_atributo AND id_atributo=OLD.id_atributo) OR EXISTS (SELECT 1 FROM VALOR_PERFIL_ANALISE WHERE id_mecanica_sistema_atributo=OLD.id_mecanica_sistema_atributo AND id_atributo=OLD.id_atributo) THEN RAISE(ABORT, 'Aplicabilidade utilizada: crie nova versao') END;
END;

CREATE TRIGGER mecanica_atributo_preservada_replace BEFORE INSERT ON MECANICA_ATRIBUTO
BEGIN
    SELECT CASE WHEN EXISTS (SELECT 1 FROM MECANICA_ATRIBUTO WHERE id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo AND id_atributo=NEW.id_atributo) AND (EXISTS (SELECT 1 FROM VALOR_ATRIBUTO_POKEMON WHERE id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo AND id_atributo=NEW.id_atributo) OR EXISTS (SELECT 1 FROM VALOR_PERFIL_ANALISE WHERE id_mecanica_sistema_atributo=NEW.id_mecanica_sistema_atributo AND id_atributo=NEW.id_atributo)) THEN RAISE(ABORT, 'Aplicabilidade utilizada nao admite substituicao implicita') END;
END;

CREATE TRIGGER forma_identidade_preservada BEFORE UPDATE ON FORMA
BEGIN
    SELECT CASE WHEN (NEW.id_especie IS NOT OLD.id_especie OR NEW.codigo_forma IS NOT OLD.codigo_forma) AND EXISTS (SELECT 1 FROM DADOS_FORMA_JOGO WHERE id_forma=OLD.id_forma) THEN RAISE(ABORT, 'Forma utilizada nao pode mudar de identidade') END;
END;

CREATE TRIGGER natureza_efeito_preservado BEFORE UPDATE ON NATUREZA
BEGIN
    SELECT CASE WHEN (NEW.estado_efeito IS NOT OLD.estado_efeito OR NEW.atributo_aumentado IS NOT OLD.atributo_aumentado OR NEW.atributo_reduzido IS NOT OLD.atributo_reduzido) AND (EXISTS (SELECT 1 FROM POKEMON_COLECAO WHERE id_natureza=OLD.id_natureza) OR EXISTS (SELECT 1 FROM PERFIL_NATUREZA WHERE id_natureza=OLD.id_natureza)) THEN RAISE(ABORT, 'Natureza utilizada exige revisao explicita antes de mudar efeito') END;
END;

CREATE TRIGGER sistema_codigo_preservado BEFORE UPDATE OF codigo ON SISTEMA_ATRIBUTO
BEGIN
    SELECT CASE WHEN NEW.codigo IS NOT OLD.codigo AND EXISTS (SELECT 1 FROM MECANICA_SISTEMA_ATRIBUTO WHERE id_sistema_atributo=OLD.id_sistema_atributo) THEN RAISE(ABORT, 'Sistema utilizado nao pode mudar de codigo') END;
END;

CREATE TRIGGER atributo_codigo_preservado BEFORE UPDATE OF codigo ON ATRIBUTO_BATALHA
BEGIN
    SELECT CASE WHEN NEW.codigo IS NOT OLD.codigo AND (EXISTS (SELECT 1 FROM MECANICA_ATRIBUTO WHERE id_atributo=OLD.id_atributo) OR EXISTS (SELECT 1 FROM VALOR_ATRIBUTO_POKEMON WHERE id_atributo=OLD.id_atributo) OR EXISTS (SELECT 1 FROM VALOR_PERFIL_ANALISE WHERE id_atributo=OLD.id_atributo)) THEN RAISE(ABORT, 'Atributo utilizado nao pode mudar de codigo') END;
END;

